async function pdfBlob(q){if(!q?.pdf)throw Error('Este presupuesto todavía no tiene PDF.');const response=await fetch(q.pdf,{credentials:'same-origin',cache:'no-store'});if(!response.ok)throw Error('No pudimos abrir el PDF.');const blob=await response.blob();if(blob.type&&blob.type!=='application/pdf')throw Error('El archivo recibido no es un PDF válido.');return blob.type==='application/pdf'?blob:new Blob([blob],{type:'application/pdf'});}
