async function downloadQuotePdf(q){window.AMCBusy?.start();try{const blob=await pdfBlob(q),name=pdfFileName(q);if(window.AMCNative?.savePdf){window.AMCNative.savePdf(await blobBase64(blob),name,false);return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.rel='noopener';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}finally{window.AMCBusy?.stop();}}
