let sessionEpoch=0,loggingOut=false;const activeRequests=new Map(),instantRequests=new Set(['/api/notices/read','/api/staff-chat/read']);
async function api(url,body,method='POST'){const key=method+' '+url+' '+JSON.stringify(body||{});if(activeRequests.has(key))return activeRequests.get(key);const chatMutation=url==='/api/staff-chat/messages'||/^\/api\/requests\/[^/]+\/messages$/.test(url),visible=method!=='GET'&&!instantRequests.has(url)&&!chatMutation;const task=(async()=>{if(visible)window.AMCBusy?.start();try{const r=await fetch(url,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf||''},...(method!=='GET'?{body:JSON.stringify(body||{})}:{})});const result=await r.json();if(!r.ok){const error=Error(result.error||'No se pudo completar la operación.');Object.assign(error,result);throw error;}return result;}finally{if(visible)window.AMCBusy?.stop();activeRequests.delete(key);}})();activeRequests.set(key,task);return task;}
const clientStateSignature=value=>value?.user?.role==='client'?JSON.stringify({user:value.user,requests:value.requests,quotes:value.quotes,works:value.works,closures:value.closures,dateProposals:value.dateProposals,appointments:value.appointments,extras:value.extras,receipts:value.receipts,notices:value.notices,chatUnread:value.chatUnread,myReview:value.myReview}):'';
let lastNoticeRouteKey='';
function paintNoticeCount(){const el=document.querySelector('#notice-count'),count=(state.notices||[]).filter(n=>!n.read).length;if(el){el.textContent=count;el.hidden=!count;}return count;}
function applyNoticeRead(ids=[]){if(!ids?.length)return;const read=new Set(ids);for(const n of state.notices||[])if(read.has(n.id)){n.read=true;n.readAt=n.readAt||new Date().toISOString();}paintNoticeCount();for(const id of read){const card=document.querySelector('[data-notice-card="'+CSS.escape(id)+'"]');if(card){card.classList.remove('unread');card.querySelector('[data-notice-state]')?.replaceChildren(document.createTextNode('Leído'));}try{window.AMCNative?.clearNotification?.(id);}catch{}}try{navigator.serviceWorker?.controller?.postMessage({type:'AMC_NOTICE_READ',ids:[...read]});}catch{}}
async function syncVisibleNotices(){if(!state.user||page==='avisos')return;const unread=(state.notices||[]).filter(n=>!n.read);if(!unread.length)return;const route='#'+page,key=state.user.id+'|'+route+'|'+unread.map(n=>n.id).join(',');if(key===lastNoticeRouteKey)return;lastNoticeRouteKey=key;try{const result=await api('/api/notices/read',{route});applyNoticeRead(result.noticeIds||[]);}catch{lastNoticeRouteKey='';}}
let offlineSnapshotSignature='';async function syncEmployeeOffline(next){if(next?.user?.role!=='employee')return;const signature=JSON.stringify((next.assignments||[]).map(t=>[t.id,t.status,t.day,t.time,t.address,t.instructions]));if(signature===offlineSnapshotSignature)return;offlineSnapshotSignature=signature;try{await cacheEmployeeSnapshot(next);}catch{}}async function reload(){const epoch=sessionEpoch;const next=await api('/api/state',null,'GET');if(epoch===sessionEpoch){state=next;syncEmployeeOffline(next);}return next;}
