function quotes(selectedId=''){const rows=selectedId?state.quotes.filter(q=>q.id===selectedId):state.quotes;return heading('TU PROYECTO','Presupuestos recibidos')+(rows.length?rows.map(q=>`<article class="panel quote" data-quote-id="${q.id}"><div class="title-row"><h2>${esc(q.number||'Presupuesto AMC')}</h2><span class="status">${esc(features.badge(q))}</span></div>${features.timeline(q)}${features.deadline(q)}<small>Enviado el ${date(q.date)}</small><ul>${q.items.map(i=>`<li>${esc(i.description)}</li>`).join('')}</ul><div class="big-price">${money(q.total)}</div><p>${esc(q.payment)}</p><p>${esc(q.notes)}</p>${q.pdf?`<button type="button" class="inline-action" data-action="download-quote-pdf" data-id="${q.id}">Descargar PDF</button>`:`<span class="status pdf-pending">PDF pendiente de generar</span>`}${!isAdmin()&&q.status==='Enviado'?`<form id="reply-${q.id}" class="quote-reply" data-id="${q.id}"><label>Comentario opcional<textarea name="message" rows="2"></textarea></label><label>Si no continuás, podés indicar el motivo<select name="reason"><option value="">Sin indicar</option><option>Precio</option><option>Decidí no realizarlo</option><option>Lo haré más adelante</option><option>Otro</option></select></label><div class="quote-actions"><button type="submit" name="status" value="Aceptado" class="primary">Aceptar presupuesto</button><button type="submit" name="status" value="Cambios solicitados">Pedir cambios</button><button type="submit" name="status" value="Rechazado">No aceptar</button></div></form>`:''}${q.reply?`<p>Tu respuesta: ${esc(q.reply)}</p>`:''}</article>`).join(''):empty('Todavía no recibiste presupuestos','Cuando AMC te envíe uno, lo vas a encontrar acá.'));}
function works(){const ws=state.works||[],w=ws.find(x=>x.id===workId)||ws[0];if(!w)return heading('SEGUIMIENTO','Mi obra')+empty('Tu obra va a aparecer acá','Primero recibís un presupuesto. Cuando lo aceptás se habilita su seguimiento.');workId=w.id;const paid=w.payments.reduce((a,p)=>a+p.amount,0);return heading('MI OBRA',esc(w.title),esc(w.address))+`<label class="work-switch">Elegir obra<select id="work-select">${ws.map(x=>`<option value="${x.id}" ${x.id===w.id?'selected':''}>${esc(x.title)} · ${x.id.slice(-6)}</option>`).join('')}</select></label><section class="panel"><span class="status">${esc(w.status)}</span><div class="dates"><span>Inicio estimado<strong>${date(w.start)}</strong></span><span>Finalización estimada<strong>${date(w.end)}</strong></span></div></section><div class="stats"><div><small>Presupuesto vigente</small><strong>${money(w.budget)}</strong>${w.baseBudget?`<small>Original: ${money(w.baseBudget)}</small>`:''}</div><div><small>Pagos registrados</small><strong>${money(paid)}</strong></div><div class="balance"><small>Saldo</small><strong>${money(w.budget-paid)}</strong></div></div><div class="two-cols"><section class="panel"><a class="inline-action" href="#cierre">Cierre de obra →</a><h2>Avances</h2>${w.updates.map(u=>`<article class="updates"><img src="${esc(u.image)}" alt="Avance de obra"><small>${date(u.date)}</small><p>${esc(u.text)}</p></article>`).join('')||'<p>AMC todavía no publicó avances.</p>'}</section><section class="panel"><h2>Pagos registrados</h2><button type="button" class="primary" data-action="payment-pdf" data-id="${w.id}">PDF con pagos y saldo</button><a href="#comprobantes" class="inline-action">Ver o enviar comprobante</a><a href="#adicionales" class="text-button">Revisar adicionales →</a>${w.payments.map(p=>`<div class="line"><span>${esc(p.description)}<small>${date(p.date)}</small></span><b>${money(p.amount)}</b></div>`).join('')||'<p>Todavía no se registraron pagos.</p>'}<p class="muted">Registro de pagos acordados con AMC. Esta aplicación no cobra dinero.</p></section></div>`;}
function notices(){const unread=(state.notices||[]).filter(n=>!n.read).length;return (state.user?.role==='employee'?'<a class="inline-action" href="/offline.html">Trabajo sin conexión →</a>':'')+heading('SIEMPRE AL TANTO','Avisos',unread?unread+' pendiente'+(unread===1?'':'s')+' de revisar.':'No tenés avisos pendientes.')+`<div class="pill-nav">${btn('Habilitar avisos en este dispositivo','enable-push')}${btn('Escuchar sonido','test-sound','','outline')}${unread?btn('Marcar todos como leídos','read','','outline'):''}</div><p class="muted">Cuando abrís el contenido relacionado —por ejemplo un chat, presupuesto, tarea o cierre— el aviso se marca leído automáticamente.</p>${(state.notices||[]).map(n=>`<article class="notification ${n.read?'':'unread'}" data-notice-card="${esc(n.id)}" data-priority="${esc(n.priority||'normal')}"><div><div class="title-row"><strong>${esc(n.title)}</strong><small data-notice-state>${n.read?'Leído':'Pendiente'}</small></div><p>${esc(n.body)}</p><small>${date(n.date)}</small><a data-notice="${n.id}" href="${esc(n.url)}">${n.read?'Ver de nuevo':'Ver'} →</a></div></article>`).join('')||empty('No tenés avisos','Las novedades de tus pedidos aparecerán acá.')}`;}
function reviews(){const canReview=state.user?.role==='client'&&(state.works||[]).some(w=>w.status==='Finalizado'),reviewBox=canReview?`<form id="review" class="panel"><h2>Contanos tu experiencia</h2><p>Tu obra ya finalizó. La reseña se publica después de revisión.</p><label>Calificación<select name="rating">${options([5,4,3,2,1],state.myReview?.rating||5)}</select></label><label>Tu opinión<textarea name="text" required minlength="10" maxlength="1500" rows="4">${esc(state.myReview?.text||'')}</textarea></label><button type="submit" class="primary">${state.myReview?'Guardar cambios':'Enviar reseña'}</button></form>`:state.user?.role==='client'?'<section class="panel"><h2>Reseña disponible al finalizar</h2><p>Podrás dejar tu opinión cuando una obra figure como finalizada.</p></section>':!state.user?'<a href="#ingresar">Ingresar para escribir una reseña</a>':'',pending=isAdmin()?`<section><h2>Pendientes de revisión</h2>${(state.pendingReviews||[]).map(r=>`<article class="panel"><div class="title-row"><strong>${esc(r.name)}</strong><span class="status">${'★'.repeat(r.rating)}</span></div><p>${esc(r.text)}</p><small>${date(r.date)}</small><button class="primary" data-action="approve-review" data-id="${esc(r.id)}">Aprobar y publicar</button></article>`).join('')||'<p>No hay reseñas pendientes.</p>'}</section>`:'';return heading('EXPERIENCIAS',isAdmin()?'Reseñas':'Reseñas de clientes',isAdmin()?'Revisá antes de publicar una opinión.':'')+`<div class="two-cols">${pending}<section><h2>Publicadas</h2>${state.reviews.map(r=>`<article class="panel"><div class="stars" aria-label="${r.rating} estrellas">${'★'.repeat(r.rating)}</div><p>${esc(r.text)}</p><strong>${esc(r.name)}</strong><small>${date(r.date)}</small></article>`).join('')||empty('La confianza se construye','Las reseñas aprobadas aparecerán acá.')}</section>${reviewBox}</div>`;}
function referrals(){return heading('RECOMENDÁ AMC','Referidos','Compartí la web con alguien que quiera renovar su casa.')+`<section class="panel">${btn('Compartir AMC','share')}<p class="muted">No hay descuentos ni recompensas automáticas.</p></section><form id="referral" class="panel reader">${field('Nombre de la persona','name')}<label>Nota opcional<textarea name="note" rows="2"></textarea></label><button type="submit" class="primary">Guardar recomendación</button></form><section class="panel">${state.referrals.map(r=>`<div class="line"><span>${esc(r.name)}<small>${esc(r.note)}</small></span><small>${date(r.date)}</small></div>`).join('')||'<p>Sin recomendaciones registradas.</p>'}</section>`;}
const adminChip=(label,group,current)=>`<button data-admin-filter="${group}" data-value="${esc(label)}" aria-pressed="${label===current}">${esc(label)}</button>`,adminBadge=value=>`<span class="admin-v3-badge" data-status="${esc(value)}">${esc(value)}</span>`,adminRequest=id=>state.requests.find(r=>r.id===id)||{},adminClient=id=>state.clients.find(c=>c.id===id)||{},adminAgendaClient=id=>(state.agendaClients||state.clients||[]).find(c=>c.id===id)||null,adminRequestContact=r=>adminAgendaClient(r?.leadId||r?.userId)||r||{},latestClosureFor=workId=>(state.closures||[]).filter(c=>c.workId===workId).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')))[0],closureNeedsAction=w=>w?.status==='Finalizado'&&(!latestClosureFor(w.id)||latestClosureFor(w.id).status==='Observaciones'),quoteCanEdit=q=>['Guardado','Entregado','Enviado','Cambios solicitados'].includes(q?.status),quoteCanRevise=q=>['Rechazado','Vencido'].includes(q?.status);
