window.AMCMediaMetrics=window.AMCMediaMetrics||[];
const canvasBlob=(canvas,type,quality)=>new Promise(resolve=>canvas.toBlob(resolve,type,quality));
async function decodeImageSource(file){try{const bitmap=await createImageBitmap(file);return {source:bitmap,width:bitmap.width,height:bitmap.height,cleanup:()=>bitmap.close?.()};}catch{const url=URL.createObjectURL(file),image=new Image();try{await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('decode'));image.src=url;});return {source:image,width:image.naturalWidth,height:image.naturalHeight,cleanup:()=>URL.revokeObjectURL(url)};}catch{URL.revokeObjectURL(url);return null;}}}
async function prepareImage(file){const started=performance.now(),decoded=await decodeImageSource(file);if(!decoded){if(file.size<=6*1024*1024)return {output:file,thumbnail:null,metrics:{originalBytes:file.size,uploadedBytes:file.size,width:0,outputWidth:0,compressed:false,mime:file.type,prepareMs:Math.round(performance.now()-started),decodeFallback:true}};throw Error('No pudimos preparar esta foto. Probá con otra imagen o sacala nuevamente.');}const {source,width,height,cleanup}=decoded,long=Math.max(width,height),target=1440,smallEnough=file.size<=500*1024&&long<=target;let output=file,outputLong=long;try{if(!smallEnough){await new Promise(requestAnimationFrame);const ratio=Math.min(1,target/long),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(width*ratio));canvas.height=Math.max(1,Math.round(height*ratio));outputLong=Math.max(canvas.width,canvas.height);canvas.getContext('2d',{alpha:false}).drawImage(source,0,0,canvas.width,canvas.height);output=await canvasBlob(canvas,'image/webp',.74)||await canvasBlob(canvas,'image/jpeg',.76);}const thumbScale=Math.min(1,320/long),thumbCanvas=document.createElement('canvas');thumbCanvas.width=Math.max(1,Math.round(width*thumbScale));thumbCanvas.height=Math.max(1,Math.round(height*thumbScale));thumbCanvas.getContext('2d',{alpha:false}).drawImage(source,0,0,thumbCanvas.width,thumbCanvas.height);const thumbnail=await canvasBlob(thumbCanvas,'image/jpeg',.62);return {output,thumbnail,metrics:{originalBytes:file.size,uploadedBytes:output.size,width:Math.round(long),outputWidth:Math.round(outputLong),compressed:output!==file,mime:output.type,prepareMs:Math.round(performance.now()-started)}};}finally{cleanup();}}
window.AMCPrepareImage=prepareImage;
function uploadWithProgress(file,thumbnail,onProgress){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest(),started=performance.now(),data=new FormData();data.append('file',file,file.name||'foto');if(thumbnail?.size)data.append('thumbnail',thumbnail,'miniatura.jpg');xhr.open('POST','/api/upload');xhr.timeout=90000;xhr.setRequestHeader('X-CSRF-Token',state.csrf||'');xhr.upload.onprogress=e=>onProgress?.(e.lengthComputable?Math.round(e.loaded/e.total*100):null);xhr.upload.onload=()=>onProgress?.(100);xhr.onload=()=>{let result;try{result=JSON.parse(xhr.responseText);}catch{return reject(Error('No pudimos confirmar la subida. Volvé a intentar.'));}if(xhr.status>=200&&xhr.status<300)resolve({...result,uploadMs:Math.round(performance.now()-started)});else reject(Error(result.error||'No se pudo subir la foto.'));};xhr.onerror=()=>reject(Error('Se cortó la conexión. La foto sigue adjunta; volvé a intentar.'));xhr.ontimeout=()=>reject(Error('La subida tardó demasiado. Revisá la conexión y volvé a intentar.'));xhr.send(data);});}
async function upload(file,onProgress,showBusy=true){if(!file||!file.size)throw Error('Elegí una foto.');if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15*1024*1024)throw Error('Usá JPG, PNG o WebP de hasta 15 MB.');if(showBusy)window.AMCBusy?.start();try{const prepared=await prepareImage(file),result=await uploadWithProgress(prepared.output,prepared.thumbnail,onProgress),metric={date:new Date().toISOString(),...prepared.metrics,uploadMs:result.uploadMs,totalMs:prepared.metrics.prepareMs+result.uploadMs};window.AMCMediaMetrics.push(metric);if(window.AMCMediaMetrics.length>30)window.AMCMediaMetrics.shift();return {...result,metric};}finally{if(showBusy)window.AMCBusy?.stop();}}
async function enablePush(){if(window.AMCNative){localStorage.setItem('amc-push-enabled','1');window.AMCNative.requestNotifications();return;}if(!('serviceWorker'in navigator)||!('PushManager'in window))throw Error('Este navegador no admite avisos push. La bandeja sigue disponible.');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('No se habilitaron avisos. Podés cambiarlo en los permisos del navegador.');registration=await navigator.serviceWorker.ready;const key=Uint8Array.from(atob(config.webPushKey.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));const sub=await registration.pushManager.getSubscription()||await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});const result=await api('/api/devices',{kind:'web',subscription:sub.toJSON()});localStorage.setItem('amc-device-id',result.deviceId);toast('Notificaciones habilitadas en este dispositivo.');}
